package com.example.takura.communications.application;
import com.fasterxml.jackson.databind.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.Timestamp;import java.time.Clock;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SesEventService{private final JdbcTemplate jdbc;private final ObjectMapper json;private final Clock clock;private final SnsSignatureVerifier verifier;private final String topic;public SesEventService(JdbcTemplate jdbc,ObjectMapper json,Clock clock,SnsSignatureVerifier verifier,@Value("${takura.communications.ses.sns-topic-arn:disabled}")String topic){this.jdbc=jdbc;this.json=json;this.clock=clock;this.verifier=verifier;this.topic=topic;}
 @Transactional public void accept(byte[] body){if(body.length>262144)throw new IllegalArgumentException("WEBHOOK_TOO_LARGE");try{JsonNode envelope=json.readTree(body);if(!topic.equals(envelope.path("TopicArn").asText())||!verifier.verify(envelope))throw new SecurityException("SNS_SIGNATURE_INVALID");String eventId=envelope.path("MessageId").asText();if(eventId.isBlank())throw new SecurityException("SNS_EVENT_ID_REQUIRED");JsonNode message=json.readTree(envelope.path("Message").asText());String type=message.path("notificationType").asText();String mailId=message.path("mail").path("messageId").asText();UUID outbox=findOutbox(mailId);int inserted=jdbc.update("INSERT INTO takura.provider_event(provider,provider_event_id,event_type,notification_id,received_at,safe_outcome) VALUES('SES',?,?,?,?,?) ON CONFLICT DO NOTHING",eventId,type,outbox,Timestamp.from(clock.instant()),safeType(type));if(inserted==0)return;if(outbox!=null)jdbc.update("UPDATE takura.notification_outbox SET provider_reference=COALESCE(provider_reference,?),state=CASE WHEN ?='Delivery' THEN 'DELIVERED' ELSE state END,completed_at=CASE WHEN ?='Delivery' THEN ? ELSE completed_at END WHERE id=?",mailId,type,type,Timestamp.from(clock.instant()),outbox);if("Bounce".equals(type)||"Complaint".equals(type)){JsonNode recipients="Bounce".equals(type)?message.path("bounce").path("bouncedRecipients"):message.path("complaint").path("complainedRecipients");for(JsonNode r:recipients){String email=r.path("emailAddress").asText();if(!email.isBlank())jdbc.update("INSERT INTO takura.communication_suppression(id,channel,destination_hash,reason,provider_reference,created_at) VALUES(?,'EMAIL',?,?,?,?) ON CONFLICT(channel,destination_hash) DO UPDATE SET active=true,reason=excluded.reason,provider_reference=excluded.provider_reference",UUID.randomUUID(),hash(email.toLowerCase()),type.toUpperCase(),mailId,Timestamp.from(clock.instant()));}}}catch(SecurityException e){throw e;}catch(Exception e){throw new IllegalArgumentException("SNS_EVENT_INVALID",e);}}
 private UUID findOutbox(String ref){var rows=jdbc.query("SELECT id FROM takura.notification_outbox WHERE provider_reference=?",(rs,n)->(UUID)rs.getObject(1),ref);return rows.isEmpty()?null:rows.getFirst();}private static String safeType(String t){return switch(t){case "Delivery"->"DELIVERED";case "Bounce"->"SUPPRESSED_BOUNCE";case "Complaint"->"SUPPRESSED_COMPLAINT";default->"IGNORED";};}private static String hash(String v)throws Exception{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}}
